<?php
require_once 'connexion.php';
$sql = 'SELECT e.nom_employe, e.prenom_employe, s.nom_service FROM employe e JOIN service s ON e.id_service = s.id_service WHERE s.id_service = 2';
try { $resultats = $pdo->query($sql)->fetchAll(); } catch (PDOException $e) { $resultats = []; $erreur = $e->getMessage(); }
?><!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Requête n°3</title><link rel="stylesheet" href="CSS/style.css"></head><body><header class="site-header"><h1>Requête n°3</h1><nav><?php for ($i=1;$i<=10;$i++): ?><a class="<?= $i===3?'active':'' ?>" href="requete<?= $i ?>.php">Requête <?= $i ?></a><?php endfor; ?></nav></header><main class="container"><p class="description">Afficher les salariés du service n°2 avec le nom du service.</p><?php if(isset($erreur)): ?><p class="error">Erreur : <?= htmlspecialchars($erreur) ?></p><?php elseif(!$resultats): ?><p class="empty">Aucun salarié trouvé.</p><?php else: ?><div class="table-wrapper"><table><thead><tr><th>Nom</th><th>Prénom</th><th>Nom du service</th></tr></thead><tbody><?php foreach($resultats as $ligne): ?><tr><td><?= htmlspecialchars($ligne['nom_employe']) ?></td><td><?= htmlspecialchars($ligne['prenom_employe']) ?></td><td><?= htmlspecialchars($ligne['nom_service']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main></body></html>
